        "resourceType": "Observation",
        "id": "observation-8",
        "status": "final",
        "code": {
          "text": "Urine dip"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Glucose ++; ketones ++; nitrite negative; leucocytes negative"
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-9",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-9",
        "status": "final",
        "code": {
          "text": "Reported symptoms and home blood glucose"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Daughter reports 3–4 days of increased thirst, increased nocturia, and marked tiredness; home blood glucose meter read “HI” for 2 days; nausea and one episode of vomiting this morning; decreased appetite; mild generalized abdominal discomfort; mild shortness of breath (“a bit puff”). Patient reports drinking water all the time and urinating all night, and thinks the high sugar may be from energy drinks."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-10",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-10",
        "status": "final",
        "code": {
          "text": "Reported negative symptoms and recent illness history"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No chest pain or focal neurological symptoms reported. No clear infection source; mild cold last week."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-11",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-11",
        "status": "final",
        "code": {
          "text": "General appearance and hydration findings"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Looks dry and tired; dry mucous membranes; ketotic/fruity breath."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-12",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-12",
        "status": "final",
        "code": {
          "text": "Mental status and speech"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Talking in short phrases; alert and oriented; GCS 15; slow to answer."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-13",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-13",
        "status": "final",
        "code": {
          "text": "Abdominal examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Mild generalized abdominal tenderness; no guarding."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-14",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-14",
        "status": "final",
        "code": {
          "text": "Chest and cardiovascular examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Chest clear; heart sounds dual; no murmur."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-15",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-15",
        "status": "final",
        "code": {
          "text": "Neurological examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No focal neurological deficit."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-16",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-16",
        "status": "final",
        "code": {
          "text": "Status during monitoring"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Remained borderline hypotensive but stable and tachycardic; repeat values not stated."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationStatement/medication-statement-1",
      "resource": {
        "resourceType": "MedicationStatement",
        "id": "medication-statement-1",
        "status": "active",
        "medicationCodeableConcept": {
          "text": "Metformin (probable; reported as the only diabetes medication)"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "note": [
          {
            "text": "Daughter reports the patient takes diabetes tablets only; the note says probably metformin only. Dose and regimen are not stated. Patient sometimes misses the night diabetes tablet when on long-haul trips."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationRequest/medication-request-1",
      "resource": {
        "resourceType": "MedicationRequest",
        "id": "medication-request-1",
        "status": "active",
        "intent": "order",
        "medicationCodeableConcept": {
          "text": "0.9% sodium chloride"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosageInstruction": [
          {
            "text": "500 mL IV started while awaiting ambulance after phone discussion with the on-call ED registrar",
            "route": {
              "text": "IV"
            },
            "doseAndRate": [
              {
                "doseQuantity": {
                  "value": 500,
                  "unit": "mL"
                }
              }
            ]
          }
        ]
      }
    }
  ]
}
